124	    }
125	
126	    /** The percentage taken off the subtotal, 0 to 100 with up to two decimals. */
127	    public BigDecimal getDiscountPct() {
128	        return discountPct;
129	    }
130	
131	    /** The fixed amount taken off the subtotal, to the cent; 0 when the discount is a percentage. */
132	    public BigDecimal getDiscountAmount() {
133	        return discountAmount;
134	    }
135	
136	    /** The most taken off the invoice in all, line discounts included, to the cent; null when there is no cap. */
137	    public BigDecimal getDiscountCap() {
138	        return discountCap;
139	    }
140	
141	    /** Why the discount was given; null when no reason was given. */
142	    public String getDiscountReason() {
143	        return discountReason;
144	    }
145	
146	    /** Sets why the discount was given; blank is no reason. */
147	    public void setDiscountReason(String discountReason) {
148	        this.discountReason = discountReason == null || discountReason.isBlank() ? null : discountReason.strip();
149	    }
150	
151	    /** Whether the discount takes off more than a fifth of the subtotal, after any cap, and so needs a reason. */
152	    public boolean discountNeedsReason() {
153	        return discount().multiply(BigDecimal.valueOf(5)).compareTo(subtotal()) > 0;
154	    }
155	
156	    /** Whether the discount needs a reason but has none. */
157	    public boolean discountLacksReason() {
158	        return discountNeedsReason() && discountReason == null;
159	    }
160	
161	    /** Sets the percentage taken off the subtotal, clearing any fixed amount; it has already been checked. */
162	    public void setDiscountPct(BigDecimal discountPct) {
163	        this.discountPct = discountPct;
164	        this.discountAmount = BigDecimal.ZERO;
165	    }
166	
167	    /** Sets the most taken off the invoice in all, or null for no cap; it has already been checked as money. */
168	    public void setDiscountCap(BigDecimal discountCap) {
169	        this.discountCap = discountCap;
170	    }
171	
172	    /**
173	     * Sets a fixed amount taken off the subtotal, clearing any percentage; it has already been checked
174	     * as money. An amount over the subtotal is refused.
175	     */
176	    public void setDiscountAmount(BigDecimal discountAmount) {
177	        if (discountAmount.compareTo(subtotal()) > 0) {
178	            throw new InvoiceRejectedException("The discount cannot be more than the subtotal of "
179	                    + subtotal().toPlainString() + ".");
180	        }
181	        this.discountAmount = discountAmount;
182	        this.discountPct = BigDecimal.ZERO;
183	    }
184	
185	    public List<InvoiceLine> getLines() {
186	        return lines;
187	    }
188	
189	    /** Whether lines can still be added: only a draft is still being written. */
190	    public boolean isDraft() {
191	        return status == InvoiceStatus.DRAFT;
192	    }
193	
194	    /** Whether the invoice has been voided: it no longer counts, takes no payments and cannot be changed. */
195	    public boolean isVoid() {
196	        return status == InvoiceStatus.VOID;
197	    }
198	
199	    /** Voids a sent invoice. */
200	    public void markVoid() {
201	        this.status = InvoiceStatus.VOID;
202	    }
203	
204	    /** Whether the due date was set by hand; it is then kept when the invoice is sent. */
205	    public boolean isManualDueDate() {
206	        return manualDueDate;
207	    }
208	
209	    /**
210	     * Sets the due date by hand: not before the issue date nor more than {@link #MAX_DUE_DAYS} days
211	     * after it, or it is refused.
212	     */
213	    public void setDueDate(LocalDate dueDate) {
214	        if (issueDate != null && dueDate.isBefore(issueDate)) {
215	            throw new InvoiceRejectedException(
216	                    "The due date cannot be before the issue date (" + issueDate + ").");
217	        }
218	        if (issueDate != null && dueDate.isAfter(issueDate.plusDays(MAX_DUE_DAYS))) {
219	            throw new InvoiceRejectedException("The due date can be at most " + MAX_DUE_DAYS
220	                    + " days after the issue date, so no later than " + issueDate.plusDays(MAX_DUE_DAYS) + ".");
221	        }
222	        this.dueDate = dueDate;
223	        this.manualDueDate = true;
224	    }
225	
226	    /**
227	     * Marks the invoice sent, issued on the given date and due on the given date, unless its due date
228	     * was set by hand, which is kept.
229	     */
230	    public void markSent(LocalDate issueDate, LocalDate dueDate) {
231	        this.status = InvoiceStatus.SENT;
232	        this.issueDate = issueDate;
233	        if (!manualDueDate) {
234	            this.dueDate = dueDate;
235	        }
236	    }
237	
238	    /** Whether a due date set by hand is already past on the given send date. */
239	    public boolean dueDatePassedBy(LocalDate sendDate) {
240	        return manualDueDate && dueDate != null && dueDate.isBefore(sendDate);
241	    }
242	
243	    /** Puts a sent invoice back to draft, so it has to be sent again. */
244	    public void reopen() {
245	        this.status = InvoiceStatus.DRAFT;
246	    }
247	
248	    /** Days past its due date an invoice is given before it becomes overdue: a week's grace. */
249	    public static final int GRACE_DAYS = 7;
250	
251	    /**
252	     * The status on the given day once the given amount has been paid against the grand total at the
253	     * tax rate: a sent invoice with something still due more than {@link #GRACE_DAYS} days after its
254	     * due date is overdue, part paid or not.
255	     */
256	    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
257	        return statusWhenPaid(paid, null, taxRate, today);
258	    }
259	
260	    /**
261	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
262	     * paid date (null when not known) is after its due date is paid late.
263	     */
264	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
265	        if (status != InvoiceStatus.SENT) {
266	            return status;
267	        }
268	        boolean due = amountDue(paid, taxRate).signum() > 0;
269	        if (due && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
270	            return InvoiceStatus.OVERDUE;
271	        }
272	        if (paid.signum() <= 0) {
273	            return status;
274	        }
275	        if (due) {
276	            return InvoiceStatus.PART_PAID;
277	        }
278	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
279	                : InvoiceStatus.PAID;
280	    }
281	
282	    /**
283	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
284	     * tax rate, taking the payments (not reversed) in date order; null while something is still due.
285	     */
286	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
287	        BigDecimal total = total(taxRate);
288	        if (status != InvoiceStatus.SENT || total.signum() <= 0) {
289	            return null;
290	        }
291	        List<Payment> inOrder = payments.stream().filter(p -> !p.isReversed())
292	                .sorted(Comparator.comparing(Payment::getDate).thenComparing(Payment::getId)).toList();
293	        BigDecimal sum = BigDecimal.ZERO;
294	        for (Payment p : inOrder) {
295	            sum = sum.add(p.amountTo(id));
296	            if (sum.signum() > 0 && total.subtract(sum).compareTo(WRITE_OFF_LIMIT) < 0) {
297	                return p.getDate();
298	            }
299	        }
300	        return null;
301	    }
302	
303	    /**
304	     * What is still due once the given amount has been paid: the grand total less it, less anything
305	     * written off — so nothing once payments leave less than {@link #WRITE_OFF_LIMIT}.
306	     */
307	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
308	        return total(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
309	    }
310	
311	    /**
312	     * What is written off once the given amount has been paid: when payments leave less than
313	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
314	     */
315	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
316	        BigDecimal left = total(taxRate).subtract(paid);
317	        return paid.signum() > 0 && left.signum() > 0 && left.compareTo(WRITE_OFF_LIMIT) < 0
318	                ? left.setScale(2, RoundingMode.HALF_UP)
319	                : BigDecimal.ZERO.setScale(2);
320	    }
321	
322	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
323	    public BigDecimal minimumPart(BigDecimal taxRate) {
324	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(2, RoundingMode.HALF_UP);
325	    }
326	
327	    /**
328	     * Whether paying the amount on top of what was already paid is too small a part payment: under
329	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
330	     */
331	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
332	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
333	    }
334	
335	    /** Adds a line to the end of the invoice. */
336	    public void addLine(InvoiceLine line) {
337	        lines.add(line);
338	    }
339	
340	    /** Whether the invoice has the line with the given id. */
341	    public boolean hasLine(Long lineId) {
342	        return lines.stream().anyMatch(l -> lineId.equals(l.getId()));
343	    }
344	
345	    /**
346	     * Removes the line with the given id; whether the invoice had it. Refused when what is left would
347	     * be less than a fixed discount on the invoice.
348	     */
349	    public boolean removeLine(Long lineId) {
350	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
351	        if (line == null) {
352	            return false;
353	        }
354	        BigDecimal left = subtotal().subtract(line.amount());
355	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
356	            throw new InvoiceRejectedException("This line cannot be removed: the $"
357	                    + left.setScale(2).toPlainString() + " left would be less than the $"
358	                    + discountAmount.setScale(2).toPlainString() + " discount.");
359	        }
360	        lines.remove(line);
361	        return true;
362	    }
363	
364	    /**
365	     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
366	     * the subtotal would then be less than a fixed discount on the invoice.
367	     */
368	    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
369	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
370	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
371	        if (line == null) {
372	            return false;
373	        }
374	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount();
375	        BigDecimal left = subtotal().subtract(line.amount()).add(changed);
376	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
377	            throw new InvoiceRejectedException("This line cannot be changed: the $"
378	                    + left.setScale(2).toPlainString() + " subtotal would be less than the $"
379	                    + discountAmount.setScale(2).toPlainString() + " discount.");
380	        }
381	        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
382	        return true;
383	    }
384	
385	    /**
386	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
387	     * matches what a client gets by adding up the lines shown.
388	     */
389	    public BigDecimal subtotal() {
390	        return lines.stream().map(InvoiceLine::amount)
391	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
392	    }
393	
394	    /**
395	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
396	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
397	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
398	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
399	     */
400	    public BigDecimal discount() {
401	        BigDecimal discount = discountAmount.signum() > 0
402	                ? discountAmount.min(subtotal()).setScale(2, RoundingMode.HALF_UP)
403	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(2, RoundingMode.DOWN);
404	        if (discountCap == null) {
405	            return discount;
406	        }
407	        BigDecimal lineDiscounts = lines.stream().map(InvoiceLine::discount)
408	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
409	        BigDecimal left = discountCap.setScale(2, RoundingMode.HALF_UP).subtract(lineDiscounts).max(BigDecimal.ZERO.setScale(2));
410	        return discount.min(left);
411	    }
412	
413	    /**
414	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
415	     * proportion to the line amounts: each line first gets the whole cents of its exact share
416	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
417	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
418	     * equal amounts too to the lower line id. The shares add up to the discount.
419	     */
420	    public List<BigDecimal> discountShares() {
421	        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
422	        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
423	        int n = lines.size();
424	        BigInteger[] shares = new BigInteger[n];
425	        BigInteger[] leftovers = new BigInteger[n];
426	        BigInteger given = BigInteger.ZERO;
427	        for (int i = 0; i < n; i++) {
428	            if (subtotalCents.signum() == 0) {
429	                shares[i] = BigInteger.ZERO;
430	                leftovers[i] = BigInteger.ZERO;
431	            } else {
432	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
433	                // as denominator, so the remainders compare as the fractions do.
434	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount().movePointRight(2).toBigIntegerExact())
435	                        .divideAndRemainder(subtotalCents);
436	                shares[i] = qr[0];
437	                leftovers[i] = qr[1];
438	            }
439	            given = given.add(shares[i]);
440	        }
441	        List<Integer> order = new ArrayList<>();
442	        for (int i = 0; i < n; i++) {
443	            order.add(i);
444	        }
445	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
446	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount()).reversed())
447	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
448	        int left = discountCents.subtract(given).intValueExact();
449	        for (int k = 0; k < left; k++) {
450	            int i = order.get(k);
451	            shares[i] = shares[i].add(BigInteger.ONE);
452	        }
453	        List<BigDecimal> result = new ArrayList<>(n);
454	        for (BigInteger share : shares) {
455	            result.add(new BigDecimal(share, 2));
456	        }
457	        return result;
458	    }
459	
460	    /**
461	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
462	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
463	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
464	     */
465	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
466	        List<BigDecimal> shares = discountShares();
467	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
468	        for (int i = 0; i < lines.size(); i++) {
469	            InvoiceLine line = lines.get(i);
470	            taxes.add(clientTaxExempt || line.isTaxExempt() ? BigDecimal.ZERO.setScale(2)
471	                    : line.amount().subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
472	                            .setScale(2, RoundingMode.HALF_UP));
473	        }
474	        return taxes;
475	    }
476	
477	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
478	    public BigDecimal tax(BigDecimal taxRate) {
479	        return lineTaxes(taxRate).stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
480	    }
481	
482	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
483	    public BigDecimal total(BigDecimal taxRate) {
484	        return subtotal().subtract(discount()).add(tax(taxRate));
485	    }
486	}
