362	     * Records a payment of the amount on the date against a sent invoice that still has something
363	     * due, and records it in the audit; empty if no such invoice. The amount has already been
364	     * checked; a draft, an invoice already paid, an amount over what is due, or a date after today
365	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
366	     * already been checked; one that belongs to a different invoice is refused.
367	     */
368	    @Transactional
369	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
370	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
371	        found.ifPresent(invoice -> {
372	            if (invoice.isDraft()) {
373	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
374	            }
375	            if (invoice.isVoid()) {
376	                throw new InvoiceRejectedException("A void invoice takes no payments.");
377	            }
378	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
379	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
380	            if (due.signum() <= 0) {
381	                throw new InvoiceRejectedException("This invoice has already been paid.");
382	            }
383	            if (amount.compareTo(due) > 0) {
384	                throw new InvoiceRejectedException("The payment is more than the $" + due.toPlainString() + " due.");
385	            }
386	            if (invoice.isTooSmallPart(amount, paidSoFar, taxRate.percent())) {
387	                throw new InvoiceRejectedException("A part payment must be at least $"
388	                        + invoice.minimumPart(taxRate.percent()).toPlainString()
389	                        + " (10% of the total), unless it settles the invoice.");
390	            }
391	            LocalDate now = today.date();
392	            if (date.isAfter(now)) {
393	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
394	            }
395	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
396	                throw new InvoiceRejectedException(
397	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
398	            }
399	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
400	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
401	                        + " is the reference of a different invoice; this invoice's is "
402	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
403	            }
404	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, date, reference));
405	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
406	                    + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
407	            recordWriteOff(invoice);
408	        });
409	        return found;
410	    }
