412	    /**
413	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
414	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
415	     * paying each off in full before the next.
416	     * A payment more than everything the client owes is refused; otherwise it is checked and recorded
417	     * as a split payment over the invoices it reaches.
418	     * References (empty when none, each already checked) instead limit the payment to the client's
419	     * invoices with those references, applied in the same order; one that is not the reference of any
420	     * of the client's invoices is refused, as is a payment more than those invoices owe together.
421	     * The payment keeps the reference of the first invoice it reaches.
422	     */
423	    @Transactional
424	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
425	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
426	        List<Invoice> candidates = ofClient;
427	        if (!references.isEmpty()) {
428	            Set<Long> named = new HashSet<>();
429	            for (String reference : references) {
430	                Invoice invoice = ofClient.stream()
431	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
432	                        .findFirst()
433	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
434	                                + " is not the reference of any of this client's invoices."));
435	                String number = InvoiceNumber.of(invoice.getId());
436	                if (invoice.isDraft()) {
437	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
438	                }
439	                if (invoice.isVoid()) {
440	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
441	                }
442	                named.add(invoice.getId());
443	            }
444	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
445	        }
446	        List<Invoice> sent = candidates.stream()
447	                .filter(i -> !i.isDraft() && !i.isVoid())
448	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
449	                        .thenComparing(Invoice::getId))
450	                .toList();
451	        Map<Long, BigDecimal> paid = paid(sent);
452	        BigDecimal owed = BigDecimal.ZERO;
453	        BigDecimal left = amount;
454	        List<PaymentAllocation> parts = new ArrayList<>();
455	        for (Invoice invoice : sent) {
456	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
457	            if (due.signum() <= 0) {
458	                continue;
459	            }
460	            owed = owed.add(due);
461	            if (left.signum() > 0) {
462	                BigDecimal part = left.min(due);
463	                parts.add(new PaymentAllocation(invoice.getId(), part));
464	                left = left.subtract(part);
465	            }
466	        }
467	        if (owed.signum() <= 0) {
468	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
469	                    : "Those invoices have already been paid.");
470	        }
471	        if (left.signum() > 0) {
472	            throw new InvoiceRejectedException("The payment is more than the $" + owed.setScale(2).toPlainString()
473	                    + (references.isEmpty() ? " the client owes." : " those invoices owe together."));
474	        }
475	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
476	        return recordSplitPayment(clientId, amount, date, reference, parts);
477	    }
