479	    /**
480	     * Records one payment of the amount on the date spread over several of the client's invoices, and
481	     * records each part in the audit. The amounts have already been checked to be more than zero; they
482	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
483	     * and be no more than what it still has due. The date must be no later than today nor before any
484	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
485	     * be the reference of one of the invoices.
486	     */
487	    @Transactional
488	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
489	            List<PaymentAllocation> parts) {
490	        if (parts.isEmpty()) {
491	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
492	        }
493	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
494	        if (sum.compareTo(amount) != 0) {
495	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
496	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
497	        }
498	        LocalDate now = today.date();
499	        if (date.isAfter(now)) {
500	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
501	        }
502	        Set<Long> seen = new HashSet<>();
503	        List<Invoice> spreadOver = new ArrayList<>();
504	        for (PaymentAllocation part : parts) {
505	            if (!seen.add(part.getInvoiceId())) {
506	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
507	            }
508	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
509	                    .filter(i -> i.getClientId().equals(clientId))
510	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
511	            String number = InvoiceNumber.of(invoice.getId());
512	            if (invoice.isDraft()) {
513	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
514	            }
515	            if (invoice.isVoid()) {
516	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
517	            }
518	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
519	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
520	            if (part.getAmount().compareTo(due) > 0) {
521	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
522	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
523	            }
524	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
525	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
526	                        + number + " is less than $" + invoice.minimumPart(taxRate.percent()).toPlainString()
527	                        + " (10% of its total), unless it settles the invoice.");
528	            }
529	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
530	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
531	                        + " (" + invoice.getIssueDate() + ").");
532	            }
533	            spreadOver.add(invoice);
534	        }
535	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
536	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
537	                    + " is not the reference of any of the invoices being paid.");
538	        }
539	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
540	        for (PaymentAllocation part : parts) {
541	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
542	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
543	        }
544	        spreadOver.forEach(this::recordWriteOff);
545	        return payment;
546	    }
