548	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
549	    private void recordWriteOff(Invoice invoice) {
550	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
551	        if (writtenOff.signum() > 0) {
552	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
553	        }
554	    }
