557	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
558	     * records it in the audit; empty if no such payment. A payment already reversed is refused.
559	     */
560	    @Transactional
561	    public Optional<Payment> reversePayment(Long paymentId) {
562	        Optional<Payment> found = payments.findById(paymentId);
563	        found.ifPresent(payment -> {
564	            if (payment.isReversed()) {
565	                throw new InvoiceRejectedException("This payment has already been reversed.");
566	            }
567	            payment.reverse();
568	            payments.saveAndFlush(payment);
569	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
570	                    + payment.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
