package net.officefloor.hq.app.invoices;

/**
 * Where an invoice is in its life: still being written, or sent to the client. A sent invoice is
 * part paid while some of it has been paid and some is still due, and paid once nothing is due, or
 * paid late when the payment that cleared it (taking payments in date order) came after its due date;
 * those follow from its payments and are never stored. A sent invoice with something still due
 * more than a week (the grace period) after its due date is overdue, part paid or not; that follows from the date and is never stored.
 * A sent invoice with no payments can be voided: it is then void for good, owes nothing and takes no
 * payments or changes.
 */
public enum InvoiceStatus {
    DRAFT, SENT, PART_PAID, PAID, PAID_LATE, OVERDUE, VOID
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace's tax rate: the stored {@code tax_rate} setting, a percentage such as 10. With no
 * rate set there is no tax, so the rate is 0.
 */
@Service
public class TaxRate {

    static final String TAX_RATE = "tax_rate";

    private final JdbcTemplate jdbc;

    public TaxRate(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public BigDecimal percent() {
        List<String> rate = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?",
                String.class, TAX_RATE);
        return rate.isEmpty() ? BigDecimal.ZERO : new BigDecimal(rate.get(0));
    }
}
package net.officefloor.hq.app;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace's "today": the stored {@code as_of} setting when there is one (a test's fixed
 * date), otherwise the real date. Everything date-dependent asks this instead of the system clock.
 */
@Service
public class Today {

    static final String AS_OF = "as_of";

    private final JdbcTemplate jdbc;

    public Today(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public LocalDate date() {
        List<String> asOf = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?",
                String.class, AS_OF);
        return asOf.isEmpty() ? LocalDate.now() : LocalDate.parse(asOf.get(0));
    }
}
package net.officefloor.hq.app.invoices;

import java.util.Collection;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PaymentRepository extends JpaRepository<Payment, Long> {

    /** The payments not reversed with a part allocated to the invoice, oldest first. */
    @Query("SELECT DISTINCT p FROM Payment p LEFT JOIN FETCH p.allocations WHERE p.reversed = false AND p.id IN (SELECT q.id FROM Payment q JOIN q.allocations a WHERE a.invoiceId = :invoiceId) ORDER BY p.date, p.id")
    List<Payment> findForInvoice(@Param("invoiceId") Long invoiceId);

    /** The payments not reversed with a part allocated to any of the invoices, oldest first. */
    @Query("SELECT DISTINCT p FROM Payment p LEFT JOIN FETCH p.allocations WHERE p.reversed = false AND p.id IN (SELECT q.id FROM Payment q JOIN q.allocations a WHERE a.invoiceId IN :invoiceIds) ORDER BY p.date, p.id")
    List<Payment> findForInvoices(@Param("invoiceIds") Collection<Long> invoiceIds);

    /** For each of the invoices that has been paid something, its id and the amount paid to it by payments not reversed. */
    @Query("SELECT a.invoiceId, SUM(a.amount) FROM Payment p JOIN p.allocations a WHERE p.reversed = false AND a.invoiceId IN :invoiceIds GROUP BY a.invoiceId")
    List<Object[]> paidTo(@Param("invoiceIds") Collection<Long> invoiceIds);
}
